// Copy what pdf.js fetches by name at run time into a package that depends on
// `pdfjs-dist`, beside the modules that name each file, and write the copy of
// pdf.js's worker with one line changed. See "Files fetched by name" in the root
// README. `gen-styles.ts` runs this for every package it generates that depends
// on `pdfjs-dist`, so it runs wherever `gen:styles` does; by itself:
//
//   node tooling/gen-pdfjs.ts packages/formats/pdf
//
// What it writes, all of it ignored by git, lint and prettier:
//
//   src/preview/pdfjs/cmaps/           the character maps (`*.bcmap`) and their LICENSE
//   src/preview/pdfjs/standard_fonts/  the standard fonts (`*.pfb`, `*.ttf`) and their licences
//   src/worker/pdfjs/                  the decoders' JavaScript fallbacks and their licences,
//                                      and pdf.worker.mjs (+ .d.mts): pdf.js's worker, hooked
//
// It does nothing when what it would write is there and current: the copy of the
// worker starts with the line this step writes for the installed version (the
// version and the change are in it), and every copied file is there with its
// source's size. Otherwise it writes both folders anew.
import { createHash } from 'node:crypto';
import {
  closeSync,
  copyFileSync,
  existsSync,
  mkdirSync,
  openSync,
  readdirSync,
  readFileSync,
  readSync,
  rmSync,
  statSync,
  writeFileSync,
} from 'node:fs';
import { createRequire } from 'node:module';
import { dirname, join, relative, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..');

/**
 * The one line of pdf.js's worker that is changed. A decoder's JavaScript
 * fallback (JPEG 2000; JBIG2 and fax) is imported from `${wasmUrl}${name}`, a
 * folder's address, which no host's build has; the change asks the package
 * first, through a function its worker sets on the worker's global.
 */
export const HOOKED_FROM = '`${WasmImage.#wasmUrl}${this._noWasmFilename}`);';
export const HOOKED_TO =
  'globalThis.pdfjsFallbackUrl?.(this._noWasmFilename) ?? `${WasmImage.#wasmUrl}${this._noWasmFilename}`);';

// Names the change in the copy's first line, so a change to it here makes the copy stale.
const CHANGE = createHash('sha256')
  .update(`${HOOKED_FROM}\n${HOOKED_TO}`)
  .digest('hex')
  .slice(0, 12);

/** The copy's first line: what it is generated from, and what was changed. */
export function hookedHeader(version: string): string {
  return (
    `// Generated by tooling/gen-pdfjs.ts from pdfjs-dist ${version} build/pdf.worker.mjs ` +
    '(Apache-2.0, Mozilla Foundation). One line changed: the import of a decoder fallback ' +
    `asks globalThis.pdfjsFallbackUrl(name) first (change ${CHANGE}). Do not edit.`
  );
}

/**
 * pdf.js's worker with its one line changed, and its source map's comment taken
 * out (the map is not copied). Throws unless the line is there exactly once, so
 * an upgrade of pdf.js that moves it stops the build rather than ship a worker
 * that draws a scan's images blank.
 */
export function hookWorker(code: string, version: string): string {
  const found = code.split(HOOKED_FROM).length - 1;
  if (found !== 1) {
    throw new Error(
      `gen-pdfjs: pdfjs-dist ${version} build/pdf.worker.mjs has ${found} imports of a decoder ` +
        `fallback where one was expected (${HOOKED_FROM}). pdf.js has changed: see ` +
        'tooling/gen-pdfjs.ts and the PDF format README.'
    );
  }
  const changed = code
    .replace(HOOKED_FROM, HOOKED_TO)
    .replace(/\n\/\/# sourceMappingURL=\S*\s*$/, '\n');
  return `${hookedHeader(version)}\n${changed}`;
}

/** One file to copy: from the installed `pdfjs-dist`, to the package. */
interface Copy {
  from: string;
  to: string;
}

/** What is copied from each of pdf.js's folders, and where to. */
const FOLDERS: readonly { from: string; to: string; keep: (name: string) => boolean }[] = [
  { from: 'cmaps', to: 'src/preview/pdfjs/cmaps', keep: (name) => /\.bcmap$|^LICENSE/.test(name) },
  {
    from: 'standard_fonts',
    to: 'src/preview/pdfjs/standard_fonts',
    keep: (name) => /\.(pfb|ttf)$|^LICENSE/.test(name),
  },
  {
    from: 'wasm',
    to: 'src/worker/pdfjs',
    // The two fallbacks and the licences that cover them; no `.wasm`.
    keep: (name) =>
      /^(openjpeg|jbig2)_nowasm_fallback\.js$|^LICENSE_(PDFJS_)?(OPENJPEG|JBIG2)$/.test(name),
  },
];

/** The folders this step writes, relative to the package. */
export const OUTPUTS = ['src/preview/pdfjs', 'src/worker/pdfjs'];

const HOOKED = 'src/worker/pdfjs/pdf.worker.mjs';
const HOOKED_TYPES = 'src/worker/pdfjs/pdf.worker.d.mts';

/** Where `pdfjs-dist` is installed for `pkg`, and its version. */
export function installedPdfjs(pkg: string): { dir: string; version: string } {
  const manifest = createRequire(join(pkg, 'package.json')).resolve('pdfjs-dist/package.json');
  const { version } = JSON.parse(readFileSync(manifest, 'utf8')) as { version: string };
  return { dir: dirname(manifest), version };
}

function copiesOf(pdfjs: string, pkg: string): Copy[] {
  return FOLDERS.flatMap(({ from, to, keep }) =>
    readdirSync(join(pdfjs, from))
      .filter(keep)
      .sort()
      .map((name) => ({ from: join(pdfjs, from, name), to: join(pkg, to, name) }))
  );
}

/** The first `length` bytes of a file, as text; '' when it is not there. */
function headOf(path: string, length: number): string {
  if (!existsSync(path)) return '';
  const fd = openSync(path, 'r');
  try {
    const buffer = Buffer.alloc(length);
    return buffer.toString('utf8', 0, readSync(fd, buffer, 0, length, 0));
  } finally {
    closeSync(fd);
  }
}

/** Whether what this step writes for `pkg` is there and current. */
function current(pkg: string, version: string, copies: Copy[]): boolean {
  const header = hookedHeader(version);
  if (headOf(join(pkg, HOOKED), header.length + 1) !== `${header}\n`) return false;
  if (!existsSync(join(pkg, HOOKED_TYPES))) return false;
  return copies.every(
    ({ from, to }) => existsSync(to) && statSync(to).size === statSync(from).size
  );
}

export interface Generated {
  /** False when everything was current and nothing was written. */
  wrote: boolean;
  version: string;
  files: number;
}

/**
 * Generate pdf.js's files for the package at `pkg`, from the `pdfjs-dist` it
 * resolves (or `pdfjs`, for a test).
 */
export function generatePdfjs(pkg: string, pdfjs = installedPdfjs(pkg)): Generated {
  const { dir, version } = pdfjs;
  const copies = copiesOf(dir, pkg);
  if (current(pkg, version, copies)) return { wrote: false, version, files: copies.length + 2 };

  // Checked before anything is removed, so a pdf.js that moved the line leaves
  // the last good copy where it was, and the build stops on the error.
  const hooked = hookWorker(readFileSync(join(dir, 'build/pdf.worker.mjs'), 'utf8'), version);
  for (const out of OUTPUTS) rmSync(join(pkg, out), { recursive: true, force: true });
  for (const { from, to } of copies) {
    mkdirSync(dirname(to), { recursive: true });
    copyFileSync(from, to);
  }
  writeFileSync(join(pkg, HOOKED), hooked);
  writeFileSync(
    join(pkg, HOOKED_TYPES),
    `${hookedHeader(version)}\n// Imported for its effect alone: it starts pdf.js's worker on the worker's global.\nexport {};\n`
  );
  return { wrote: true, version, files: copies.length + 2 };
}

/** Whether the package at `pkg` depends on `pdfjs-dist`, and so has its files generated. */
export function usesPdfjs(pkg: string): boolean {
  const manifest = join(pkg, 'package.json');
  if (!existsSync(manifest)) return false;
  const { dependencies = {} } = JSON.parse(readFileSync(manifest, 'utf8')) as {
    dependencies?: Record<string, string>;
  };
  return 'pdfjs-dist' in dependencies;
}

/** Generate for `pkg` and say what was done, as gen-styles says what it wrote. */
export function generateAndLog(pkg: string): void {
  const { wrote, version, files } = generatePdfjs(pkg);
  if (wrote)
    console.log(
      `gen-pdfjs: wrote ${files} files of pdfjs-dist ${version} into ${relative(root, pkg)}`
    );
}

if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  const pkg = process.argv[2];
  if (!pkg) {
    console.error('usage: node tooling/gen-pdfjs.ts <package folder>');
    process.exit(1);
  }
  generateAndLog(resolve(pkg));
}
